import type { ComponentProps } from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

const alertVariants = cva(
  "group/alert relative grid w-full gap-0.5 rounded-lg border px-2.5 py-2 text-left text-sm has-data-[slot=alert-action]:relative has-data-[slot=alert-action]:pr-18 has-[>svg]:grid-cols-[auto_1fr] has-[>svg]:gap-x-2 *:[svg]:row-span-2 *:[svg]:translate-y-0.5 *:[svg]:text-current *:[svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-muted/50 text-secondary-foreground",
        danger:
          "bg-danger-subtle border-danger text-danger-subtle-foreground **:[.text-muted-foreground]:text-danger-subtle-foreground/80",
        success:
          "bg-success-subtle border-success text-success-subtle-foreground **:[.text-muted-foreground]:text-success-subtle-foreground/80",
        warning:
          "bg-warning-subtle border-warning text-warning-subtle-foreground **:[.text-muted-foreground]:text-warning-subtle-foreground/80",
        info: "bg-info-subtle border-info text-info-subtle-foreground **:[.text-muted-foreground]:text-info-subtle-foreground/70"
      }
    },
    defaultVariants: {
      variant: "default"
    }
  }
)

const Alert = ({ className, variant, ...props }: ComponentProps<"div"> & VariantProps<typeof alertVariants>) => (
  <div className={cn(alertVariants({ variant }), className)} data-slot="alert" role="alert" {...props} />
)

const AlertTitle = ({ className, ...props }: ComponentProps<"div">) => (
  <div
    className={cn(
      "[&_a]:hover:text-foreground font-medium group-has-[>svg]/alert:col-start-2 [&_a]:underline [&_a]:underline-offset-3",
      className
    )}
    data-slot="alert-title"
    {...props}
  />
)

const AlertDescription = ({ className, ...props }: ComponentProps<"div">) => (
  <div
    className={cn(
      "text-muted-foreground [&_a]:hover:text-foreground text-sm text-balance md:text-pretty [&_a]:underline [&_a]:underline-offset-3 [&_p:not(:last-child)]:mb-4",
      className
    )}
    data-slot="alert-description"
    {...props}
  />
)

const AlertAction = ({ className, ...props }: ComponentProps<"div">) => (
  <div className={cn("absolute top-2 right-2", className)} data-slot="alert-action" {...props} />
)
Alert.Title = AlertTitle
Alert.Description = AlertDescription
Alert.Action = AlertAction

export { Alert, AlertAction, AlertDescription, AlertTitle }
